#requires -version 5.1
$ErrorActionPreference='Stop'
$projectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));Set-Location -LiteralPath $projectRoot
. (Join-Path $projectRoot 'MemoryClear.ps1') -SmokeTest -ControlsOnly
Import-Module (Join-Path $projectRoot 'app\CleanData\TempCleanup.psm1') -DisableNameChecking
$results=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Value,[string]$Message);if(-not$Value){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Action);try{&$Action;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}}
function Click {param($Button);$Button.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Primitives.ButtonBase]::ClickEvent))}
function Find-TempCheckbox {param($Node);if($Node-is[Windows.Controls.CheckBox]){return $Node};for($i=0;$i-lt[Windows.Media.VisualTreeHelper]::GetChildrenCount($Node);$i++){$found=Find-TempCheckbox ([Windows.Media.VisualTreeHelper]::GetChild($Node,$i));if($found){return $found}}}
function Wait-Temp {param($V);$clock=[Diagnostics.Stopwatch]::StartNew();$frame=New-Object Windows.Threading.DispatcherFrame;$poll=New-Object Windows.Threading.DispatcherTimer;$poll.Interval=[TimeSpan]::FromMilliseconds(100);$poll.Add_Tick({$frame.Continue=$V.Busy-and$clock.Elapsed.TotalSeconds-lt30}.GetNewClosure());try{$poll.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}finally{$poll.Stop()};Assert (-not$V.Busy) 'Actual Temp DispatcherTimer timeout'}
$root=[MemoryClear.Storage.FileInventory]::OwnTempRoot();$prefix='memoryclear-uiqa-'+[guid]::NewGuid().ToString('N');$paths=@()
foreach($name in @('old.tmp','log.log')){$path=Join-Path $root ($prefix+'-'+$name);[IO.File]::WriteAllText($path,'Own disposable Temp UI QA '+$name);[IO.File]::SetLastWriteTimeUtc($path,[DateTime]::UtcNow.AddDays(-10));$paths+=@($path)}
$v=$null
try{
    $v=New-MCTempWindow -CandidatePaths $paths
    Check 'Shared lock blocks Temp alongside RAM and scanner' {Set-MCOperationState $true;Assert (-not$diskUI.DiskClean.IsEnabled-and-not$ui.ClearMemory.IsEnabled) 'Concurrent action enabled';Set-MCOperationState $false;Assert $diskUI.DiskClean.IsEnabled 'Temp entry did not unlock'}
    Check 'Twelve controls; real background scan and DispatcherTimer completion' {Assert ($v.UI.Count-eq12-and$v.Busy-and-not$v.UI.TempRun.IsEnabled) 'Wrong controls/start state';Wait-Temp $v;Assert ($v.Rows.Count-eq2-and$v.Plan.Stage-eq'Review'-and-not$v.Busy-and-not$v.UI.TempProgress.IsIndeterminate-and$v.UI.TempStatus.Text.Contains('2 ứng viên')) 'Scan failed'}
    Check 'WPF checkbox single click updates source in both directions' {$content=$v.Window.Content;$content.Measure([Windows.Size]::new(1020,690));$content.Arrange([Windows.Rect]::new(0,0,1020,690));$content.UpdateLayout();$cell=$v.UI.TempFiles.Columns[0].GetCellContent($v.Rows[0]);$box=Find-TempCheckbox $cell;Assert ($box-and$box.IsEnabled) 'Live checkbox unavailable';$onClick=[Windows.Controls.Primitives.ToggleButton].GetMethod('OnClick',[Reflection.BindingFlags]'Instance,NonPublic');$onClick.Invoke($box,@())|Out-Null;Assert $v.Rows[0].Selected 'Single click did not select';$onClick.Invoke($box,@())|Out-Null;Assert (-not$v.Rows[0].Selected) 'Single click did not unselect';Click $v.UI.TempSelectAll;Assert (@($v.Rows|Where-Object{$_.Selected}).Count-eq2) 'Select-all failed'}
    Check 'First review freezes exact list; second acknowledgment is required' {Click $v.UI.TempNext;Assert ($v.Plan.Stage-eq'Confirm'-and$v.UI.TempAck.Visibility-eq'Visible'-and$v.UI.TempFiles.IsReadOnly-and-not$v.UI.TempRun.IsEnabled) 'Confirmation guard failed'}
    Check 'Back clears approval and re-scans only own QA paths' {Click $v.UI.TempBack;Wait-Temp $v;Assert ($v.Plan.Stage-eq'Review'-and-not@($v.Rows|Where-Object{$_.Selected}).Count-and-not$v.UI.TempAck.IsChecked) 'Back retained approval'}
    Check 'Offscreen review visual can render without showing native window' {$content=$v.Window.Content;$content.Measure([Windows.Size]::new(1020,690));$content.Arrange([Windows.Rect]::new(0,0,1020,690));$content.UpdateLayout();$bmp=[Windows.Media.Imaging.RenderTargetBitmap]::new(1020,690,96,96,[Windows.Media.PixelFormats]::Pbgra32);$bmp.Render($content);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bmp));$stream=[IO.File]::Create((Join-Path $projectRoot 'artifacts\temp-ui-preview.png'));try{$encoder.Save($stream)}finally{$stream.Dispose()}}
    Check 'Permanent Run worker deletes only exact own QA files and reports finish' {Click $v.UI.TempSelectAll;Click $v.UI.TempNext;$v.UI.TempAck.IsChecked=$true;Click $v.UI.TempAck;Click $v.UI.TempRun;Assert ($v.Busy-and-not$v.UI.TempClose.IsEnabled-and$v.UI.TempStop.IsEnabled) 'Running state missing';Wait-Temp $v;Assert ($v.Result.Status-eq'Completed'-and$v.Result.Processed-eq2-and-not[IO.File]::Exists($paths[0])-and-not[IO.File]::Exists($paths[1])-and$v.UI.TempStatus.Text.Contains('kết thúc')-and$v.Rows[0].Effect.Contains('Deleted')-and-not$v.Rows[0].Selected-and-not$v.UI.TempRun.IsEnabled) 'Run/finish not proven'}
}finally{if($v){if($v.Busy){$v.Token.Cancel();Wait-Temp $v};$v.Timer.Stop();if($v.Plan){Close-MCTempPlan $v.Plan.Id};$v.Window.Close()}}
$r=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Checks=$results.ToArray();Scope='Offscreen WPF, real DispatcherTimer/background workers, only exact own newly created QA Temp files deleted; no human/DPI acceptance';Image='artifacts/temp-ui-preview.png'}
$r|ConvertTo-Json -Depth 7|Set-Content (Join-Path $projectRoot 'docs\verification\temp-ui-tests.json') -Encoding UTF8
Write-Host ('Temp UI: '+$r.Passed+' passed, '+$r.Failed+' failed');if($r.Failed){$r.Checks|Where-Object{-not$_.Passed}|Format-List;exit 1}
